"""Self-contained, escaped HTML report built from a published session snapshot."""
from datetime import datetime,timezone
from html import escape

def text(value):return escape(str(value if value is not None else '—'),quote=True)
def stamp(value):
    try:return datetime.fromtimestamp(float(value),timezone.utc).strftime('%Y-%m-%d %H:%M:%S UTC')
    except (TypeError,ValueError,OverflowError,OSError):return 'Unknown'
def location(fix):
    if not fix:return 'No GPS-tagged sighting'
    return '%s, %s | accuracy %s m | %s'%(text(fix.get('lat')),text(fix.get('lon')),text(fix.get('accuracy_m')),text(stamp(fix.get('observed_at'))))
def render_report(state):
    devices=state.get('devices',[]);coverage=state.get('coverage',{});rows=[]
    for d in devices:
        hit=d.get('hits',[None])[0] if d.get('hits') else None
        label=text(hit.get('label'))+' (rank '+text(hit.get('score'))+')' if hit else 'Unclassified'
        evidence='<br>'.join(text(h.get('evidence','')) for h in d.get('hits',[]))
        rows.append('<tr><td><b>'+text(d.get('local_label') or d.get('network_name') or d.get('name') or 'Unnamed')+'</b><br>'+text(d.get('address'))+'<small>'+text((d.get('security') or {}).get('label',''))+' · PMF: '+text((d.get('security') or {}).get('pmf','Unknown'))+'</small></td><td>'+text(d.get('protocol'))+'</td><td>'+text(d.get('last_rssi',d.get('rssi')))+'</td><td>'+label+'<small>'+evidence+'</small></td><td>'+location(d.get('last_location'))+'</td><td>'+location(d.get('strongest_location'))+'</td></tr>')
    field=state.get('field_summary') or {};duration=field.get('duration_seconds');percent=field.get('gps_coverage_percent')
    recovered=state.get('recovery') or {}
    recovery_note=('<p>Interrupted session: totals reflect the last checkpoint. Later complete logged sightings recovered: '+text(recovered.get('records',0))+'; incomplete/malformed records skipped: '+text(recovered.get('skipped',0))+('. Recovery read limit reached; consult original logs.' if recovered.get('limited') else '.')+'</p>') if recovered else ''
    field_html=recovery_note+'<h2>Field run summary</h2><div class="summary"><div><strong>'+text(round(duration/60,1) if isinstance(duration,(int,float)) else None)+'</strong>Elapsed minutes</div><div><strong>'+text(str(percent)+"%" if percent is not None else None)+'</strong>GPS coverage</div><div><strong>'+text(field.get("retained_wifi"))+'</strong>Retained Wi-Fi addresses</div><div><strong>'+text(field.get("retained_ble"))+'</strong>Retained Bluetooth addresses</div></div><p>GPS coverage: '+text(field.get("geotagged_observations"))+' tagged / '+text(field.get("observations"))+' accepted observations. Counts include observations before journal throttling or recording limits; consult log status.</p>'
    reasons=field.get('gps_reasons')
    field_html+='<p>GPS misses: '+(' · '.join(text(k)+': '+text(reasons.get(k,0)) for k in ('stale','inaccurate','unavailable')) if isinstance(reasons,dict) else 'Reason breakdown unavailable for this older run.')+'</p>'
    scanner_rows=''.join('<li><b>'+text(k)+'</b>: '+text(v.get('status',''))+'</li>' for k,v in state.get('scanners',{}).items())
    channels=''.join('<tr><td>'+text(c['frequency'])+'</td><td>'+text(c['visits'])+'</td><td>'+text(c['frames'])+'</td><td>'+text(c['rejected'])+'</td><td>'+text(stamp(c['last_rx']))+'</td></tr>' for c in coverage.get('channels',[]))
    return ('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PagerWatch session report</title><style>
:root{color-scheme:dark}body{background:#0b100e;color:#edf2e9;font:14px/1.65 system-ui,sans-serif;margin:32px auto;padding:0 24px;max-width:1500px}h1{font-size:32px;color:#c0f56b}h2{margin-top:32px}small{display:block;color:#acbaac;font-size:11px;margin-top:8px}.summary{display:flex;gap:20px;flex-wrap:wrap;background:#172218;border:1px solid #344532;padding:20px;border-radius:9px}.summary strong{font-size:28px;display:block}table{border-collapse:collapse;width:100%;font-size:12px}td,th{padding:12px;border-bottom:1px solid #344532;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{color:#c0f56b}.scroll{overflow:auto}p{color:#acbaac}footer{margin-top:30px;border-top:1px solid #344532;padding:20px 0}@media print{body{background:white;color:black}h1,th{color:#285c00}small,p{color:#444}.summary{background:#eee}.scroll{overflow:visible}td{min-width:80px}}
</style><h1>PagerWatch · Session report</h1><p>by Nester · Offline snapshot · '''+text(state.get('version',''))+'''</p><p>Session '''+text(state.get('session_label') or state.get('session',''))+'''<br>Started: '''+text(stamp(state.get('started')))+'''<br>Snapshot: '''+text(stamp(state.get('now')))+'''</p><div class="summary"><div><strong>'''+str(len(devices))+'''</strong>Retained radio addresses</div><div><strong>'''+text(state.get('processed',0))+'''</strong>Processed observations</div><div><strong>'''+text(state.get('geotagged_devices',0))+'''</strong>Located addresses</div><div><strong>'''+text(state.get('dropped',0))+'''</strong>Queue drops</div></div>'''+field_html+'''<h2>Scanner state and coverage</h2><ul>'''+scanner_rows+'''</ul><p>Visited '''+text(coverage.get('visited',0))+''' of '''+text(coverage.get('planned',0))+''' planned frequencies. Visits record channel selection, not uninterrupted reception or complete coverage. Receive counts are decoded management frames for monitor capture or AP observations for passive scan fallback, not channel utilization.</p><div class="scroll"><table><tr><th>MHz</th><th>Selections</th><th>Received observations</th><th>Rejected tunes</th><th>Last received</th></tr>'''+channels+'''</table></div><h2>Device evidence and sighting locations</h2><p>Addresses remain separate, even when names match. Coordinates indicate where the receiver heard a device; they are not measured transmitter positions. Rule ranks are not confidence probabilities or proof of an attack.</p><div class="scroll"><table><tr><th>Device / address</th><th>Radio</th><th>Last RSSI dBm</th><th>Signature / evidence</th><th>Latest GPS sighting</th><th>Strongest GPS sighting</th></tr>'''+''.join(rows)+'''</table></div><p>Log status: '''+text(state.get('log_error') or 'No recorded log error')+''' · Evicted addresses: '''+text(state.get('evicted',0))+'''</p><footer>Bounded current-session snapshot. Evicted devices and older events may remain in the JSONL / wardriving CSV log. No external scripts, fonts, map services or network resources are needed to view this report.</footer></html>''').encode('utf-8')
